'use server'

import { revalidateTag } from 'next/cache'

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string
  const content = formData.get('content') as string

  // TODO: Add your actual post creation logic here
  // For example, save to database
  // await db.posts.create({ title, content })

  console.log('Creating post:', { title, content })

  // Invalidate the "posts" cache tag
  // This ensures that the next request will fetch fresh data
  // and no stale cached content will be served
  revalidateTag('posts')

  return { success: true }
}

